(() => {
'use strict';
// Only supplied learning details appear here. Add further topics to this small list.
const topics=[{name:'C language',title:'Learning C',description:'I’m learning the C programming language.',status:'CURRENTLY LEARNING',x:27,y:48,color:'#c1dcff'},{name:'',title:'',description:'',status:'',x:67,y:29,color:'#e8d5ab'},{name:'',title:'',description:'',status:'',x:76,y:77,color:'#b4b4e0'}];
window.learningClusterMarkup=id=>'<section class="learning-cluster" data-learning-cluster="'+id+'" aria-label="My learning star clusters"><div class="learning-cluster-heading"><span>MY LEARNING UNIVERSE</span><h3>One star. A new discovery.</h3><p>Hover, tap, or use arrow keys to explore.</p></div><div class="learning-cluster-sky"><canvas aria-hidden="true"></canvas><div role="tablist" aria-label="Learning topics">'+topics.map((topic,i)=>'<button class="learning-topic-star" type="button" role="tab" id="'+id+'-star-'+i+'" aria-controls="'+id+'-learning-panel" aria-selected="'+(i===0)+'" tabindex="'+(i===0?'0':'-1')+'" aria-label="'+(topic.name||'Empty learning star '+(i+1))+'" data-learning-topic="'+i+'" style="--star-x:'+topic.x+'%;--star-y:'+topic.y+'%;--star-color:'+topic.color+'"><i aria-hidden="true"></i><span>'+topic.name+'</span></button>').join('')+'</div></div><div class="learning-cluster-card" id="'+id+'-learning-panel" role="tabpanel" aria-labelledby="'+id+'-star-0" tabindex="0"><span data-learning-status>'+topics[0].status+'</span><h4 data-learning-title>'+topics[0].title+'</h4><p data-learning-description>'+topics[0].description+'</p></div></section>';
const clusterObservers=new Map();
window.mountLearningClusters=(root=document)=>{for(const [element,observer] of clusterObservers){if(!element.isConnected){observer.disconnect();clusterObservers.delete(element)}}root.querySelectorAll('[data-learning-cluster]').forEach(cluster=>{if(cluster.dataset.mounted)return;cluster.dataset.mounted='true';const buttons=[...cluster.querySelectorAll('[role=tab]')],panel=cluster.querySelector('[role=tabpanel]');let selected=0;
function select(index,focus=false){selected=index;const topic=topics[index];buttons.forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1});panel.setAttribute('aria-labelledby',buttons[index].id);cluster.querySelector('[data-learning-status]').textContent=topic.status;cluster.querySelector('[data-learning-title]').textContent=topic.title;cluster.querySelector('[data-learning-description]').textContent=topic.description;if(focus)buttons[index].focus({preventScroll:true})}
buttons.forEach((button,i)=>{button.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')select(i)});button.addEventListener('focus',()=>select(i));button.addEventListener('click',()=>select(i));button.addEventListener('keydown',e=>{let index=selected;if(e.key==='ArrowRight'||e.key==='ArrowDown')index=(selected+1)%topics.length;else if(e.key==='ArrowLeft'||e.key==='ArrowUp')index=(selected+topics.length-1)%topics.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=topics.length-1;else return;e.preventDefault();select(index,true)})});
const canvas=cluster.querySelector('canvas'),ctx=canvas.getContext('2d');if(ctx){let lastWidth=0;const paint=()=>{const width=canvas.clientWidth,height=canvas.clientHeight;if(!width||width===lastWidth)return;lastWidth=width;const ratio=Math.min(devicePixelRatio,1.25);canvas.width=width*ratio;canvas.height=height*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);let seed=435;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};ctx.clearRect(0,0,width,height);for(const topic of topics){const x=topic.x/100*width,y=topic.y/100*height,g=ctx.createRadialGradient(x,y,0,x,y,width*.23);g.addColorStop(0,topic.color+'21');g.addColorStop(.45,topic.color+'0b');g.addColorStop(1,topic.color+'00');ctx.fillStyle=g;ctx.fillRect(0,0,width,height);for(let i=0;i<180;i++){const angle=random()*Math.PI*2,r=Math.pow(random(),1.6)*width*.24,s=.3+random()*.9;ctx.globalAlpha=.2+random()*.6;ctx.fillStyle=topic.color;ctx.beginPath();ctx.arc(x+Math.cos(angle)*r,y+Math.sin(angle)*r*.48,s,0,Math.PI*2);ctx.fill()}}ctx.globalAlpha=1};const observer=new ResizeObserver(()=>{if(!cluster.isConnected){observer.disconnect();return}paint()});clusterObservers.set(cluster,observer);observer.observe(canvas);paint()}
})};
document.querySelectorAll('[data-learning-cluster-slot]').forEach((slot,i)=>{slot.innerHTML=window.learningClusterMarkup('page-learning-'+i)});window.mountLearningClusters();document.addEventListener('click',e=>{if(!e.target.closest('[data-learning-scroll]'))return;const source=e.target.closest('.destination-info')||e.target.closest('#learning'),cluster=source?.querySelector('[data-learning-cluster]');if(cluster)cluster.scrollIntoView({behavior:document.body.classList.contains('reduced')?'instant':'smooth',block:'start'})});
})();
